1	using DAL.Interfaces;
2	using DAL.Models;
3	using EduWare.Helper;
4	using EduWareDataAccess.Models;
5	using EduWareDataAccess.Repository;
6	using System;
7	using System.Collections.Generic;
8	using System.Linq;
9	using System.Text.RegularExpressions;
10	using System.Web.Mvc;
11	using static EnumClass;
12	
13	namespace EduWare.Controllers
14	{
15	    public class ConsolidateResultReportController : BaseController
16	    {
17	        #region Global Variable Declaration
18	        IRepository<Cceconfiguration> _CCE;
19	        IRankProfile _RankProfile;
20	        ConsolidateResultRepository objConsolidateResultRepository = new ConsolidateResultRepository();
21	        ResultGradeRepository objResultGradeRepository = new ResultGradeRepository();
22	
23	        public ConsolidateResultReportController(IRepository<Cceconfiguration> cce, IRankProfile rankProfile)
24	        {
25	            _CCE = cce;
26	            _RankProfile = rankProfile;
27	        }
28	        #endregion
29	
30	        // GET: ConsolidateResultReport
31	        public ActionResult Index()
32	        {
33	            ConsolidateResultReportModel model = new ConsolidateResultReportModel();
34	            model = BindDropdown(model);
35	            return View(model);
36	        }
37	
38	        #region Bind Dropdown Datas
39	        public ConsolidateResultReportModel BindDropdown(ConsolidateResultReportModel model)
40	        {
41	            model.SchoolStandardIDSelectList = new SelectList(new CommonRepository().FillStandardBySchoolId(new CurrentSession().LoginSchoolID), "Value", "Texts", model.SchoolStandardID);
42	            model.StandardDivisionIDSelectList = new SelectList(new CommonRepository().FillStandardDivisionBySchoolStandardID(model.SchoolStandardID), "Value", "Texts");
43	            model.TermIDSelectList = new SelectList(new EnumRepository().GetFilterEnumDatas(new EnumModel() { EnumTypeID = (int)EnumEnumType.Term }), "EnumID", "EnumValue", model.TermID);
44	
45	            return model;
46	        }
47	        #endregion
48	
49	
50	        public JsonResult CheckConsolidateDataExists(int SchoolStandardID, int StandardDivisionID, int TermID)
51	        {
52	            ConsolidateResultModel crmodel = new ConsolidateResultModel();
53	            crmodel.SchoolID = new CurrentSession().LoginSchoolID;
54	            crmodel.SchoolSessionID = new CurrentSession().SchoolSessionID;
55	            crmodel.SchoolStandardID = SchoolStandardID;
56	            crmodel.StandardDivisionID = StandardDivisionID;
57	            crmodel.TermID = TermID;
58	
59	            var DataExists = new ConsolidateResultRepository().CheckDataExist(crmodel);
60	            return Json(DataExists.Count > 0, JsonRequestBehavior.AllowGet);
61	        }
62	
63	        #region Get Student List for Kendo Grid
64	        public JsonResult GetStudentList(int SchoolStandardID, int StandardDivisionID, int TermID, int OnlyAlumni = 0)
65	        {
66	            try
67	            {
68	                ConsolidateResultModel model = new ConsolidateResultModel();
69	                if (SchoolStandardID != 0 && StandardDivisionID != 0 && TermID != 0)
70	                {
71	                    ConsolidateResultModel param = new ConsolidateResultModel();
72	                    param.SchoolID = new CurrentSession().LoginSchoolID;
73	                    param.SchoolSessionID = new CurrentSession().SchoolSessionID;
74	                    param.SchoolStandardID = SchoolStandardID;
75	                    param.StandardDivisionID = StandardDivisionID;
76	                    param.TermID = TermID;
77	                    param.OnlyAlumniStudents = OnlyAlumni;
78	
79	                    var savedTable = objConsolidateResultRepository.GetSavedStudentList(param);
80	                    if (savedTable.ConsolidateResultList.Count > 0 && savedTable.FinalResult.Count > 0)
81	                    {
82	                        model = savedTable;
83	                        model.FlagForSavedData = 1;
84	                    }
85	                    else
86	                    {
87	                        model.ConsolidateResultList = objConsolidateResultRepository.GetStudentList(param);
88	                        model.FinalResult = (from Total in model.ConsolidateResultList
89	                                             group Total by Total.StudentCurrentID into TotalData
90	                                             select new FinalResultModel()
91	                                             {
92	                                                 StudentCurrentID = TotalData.Key,
93	                                                 OverallTotalBefore = TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.TotalBefore != -999).Sum(x => x.TotalBefore), /// -999 for absent
94	                                                 OverallTotalAfter = TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.ObtainedTotalMarks != -999).Sum(x => x.ObtainedTotalMarks),
95	                                                 SpecialTotal = TotalData.Sum(x => x.Special),
96	                                                 GraceTotal = TotalData.Sum(x => x.Grace),
97	                                                 CondTotal = TotalData.Sum(x => x.Cond),
98	                                                 Result = TotalData.Select(x => x.IsFailed).Any(a => a == 1) ? "Failed" : "Pass",
99	                                                 TotalofTotalMarks = TotalData.Sum(x => x.Totaltotalmarks),
100	                                                 Percentage = TotalData.Where(x => x.IsIncludeInTotal == 1).Sum(x => x.Totaltotalmarks) > 0
101	                                                     ? (TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.ObtainedTotalMarks != -999).Sum(x => x.TotalBefore) / TotalData.Where(x => x.IsIncludeInTotal == 1).Sum(x => x.Totaltotalmarks)) * 100
102	                                                     : 0,
103	                                                 RollNo = TotalData.FirstOrDefault().RollNo,
104	                                             }).ToList();
105	
106	                        // --- For Give Rank
107	                        // Rule - when any student is used condonation marks then don't apply rank on that
108	                        var prdata = model.FinalResult.OrderByDescending(a => a.Percentage)
109	                            .Where(x => x.Result == "Pass")
110	                            .Select(x => new { x.Percentage, x.Rank }).Distinct().ToList();
111	                        int i = 1;
112	                        var rankData = (from pr in prdata select new FinalResultModel() { Percentage = pr.Percentage, Rank = i++ }).ToList();
113	
114	                        CCEConfigurationModel cCEConfigurationModel = new CCEConfigurationRepository().GetFilterCCEConfigurationData(new CCEConfigurationModel() { SchoolID = param.SchoolID, SchoolSessionID = param.SchoolSessionID, SchoolStandardID = param.SchoolStandardID, TermID = param.TermID, ActiveStatus = 1 }).FirstOrDefault();
115	
116	                        ResultGradeModel GradeID = objResultGradeRepository.GetFilterResultGradeDatas(new ResultGradeModel() { SchoolID = new CurrentSession().LoginSchoolID, ResultGradeID = (cCEConfigurationModel?.ResultGradeID ?? 0) }).FirstOrDefault();
117	                        var Grade = GradeID != null ? objResultGradeRepository.GetFilterResultGradePercentageDatas(new ResultGradePercentageModel() { ResultGradeID = GradeID.ResultGradeID }) : new List<ResultGradePercentageModel>();
118	
119	                        model.FinalResult.Where(x => x.Result == "Pass").ToList().ForEach(x => x.Grade = Grade.Where(y => y.FromPercentage <= x.Percentage && y.ToPercentage >= x.Percentage).Select(y => y.GradeName).FirstOrDefault());
120	                        model.FinalResult.Where(x => x.Result == "Failed").ToList().ForEach(x => x.Grade = Grade.Where(y => y.FromPercentage <= x.Percentage && y.ToPercentage >= x.Percentage).Select(y => y.GradeName).FirstOrDefault());
121	
122	                        // Rule : when used grace marks then `Promoted` and when use condonation marks then `Pass And Promoted`
123	                        model.FinalResult
124	                            .Where(w => w.Result != "Failed")
125	                            .GroupBy(g => g.StudentCurrentID)
126	                            .ToList()
127	                            .ForEach(f =>
128	                            {
129	                                f.ToList().ForEach(e => e.Result = f.Sum(s => s.GraceTotal) > 0 && f.Sum(s => s.CondTotal) == 0 ? "Pass" : f.Sum(s => s.CondTotal) > 0 ? "Promoted" : e.Result);
130	                            });
131	
132	                        Cceconfiguration cce = _CCE.GetEntity().Where(w => w.SchoolId == param.SchoolID
133	                            && w.SchoolSessionId == param.SchoolSessionID
134	                            && w.SchoolStandardId == param.SchoolStandardID
135	                            && w.TermId == (param.TermID == 200 ? w.TermId : param.TermID)
136	                            && w.ActiveStatus == 1).OrderBy(o => o.TermId).LastOrDefault();
137	
138	                        if (cce != null)
139	                        {
140	                            RankProfile RankProfile;
141	                            if (cce.RankProfileId.HasValue && cce.RankProfileId.Value > 0)
142	                            {
143	                                RankProfile = _RankProfile.GetDefaultRankProfile(cce.RankProfileId.Value);
144	                                TempData["RankProfile"] = RankProfile;
145	
146	                                // Rule : when rank profile marked absent as fail then if a student not appear in any exam considered as fail 
147	                                model.FinalResult.OrderByDescending(a => a.Percentage)
148	                                    .Where(x => x.Result == "Pass" && model.ConsolidateResultList.Any(a => a.StudentCurrentID == x.StudentCurrentID && (RankProfile.AbsentAsFail && ((a.AbsentInAny > 0 && a.IsIncludeInTotal == 1) || (a.AbsentInAny > 0 && a.IsIncludeInTotal == 0 && RankProfile.ConsiderOptionalSubjectForResult)))))
149	                                    .ToList().ForEach(x => x.Result = "Failed");
150	
151	                                // Rule : give rank only to pass student
152	                                model.FinalResult.OrderByDescending(a => a.Percentage)
153	                                    .Where(x => x.Result == "Pass").ToList().ForEach(x => x.Rank = rankData.Where(y => y.Percentage == x.Percentage).Select(y => y.Rank).FirstOrDefault());
154	
155	                                List<ResultRankModel> StudentRank = new List<ResultRankModel>();
156	                                StudentRank = model.FinalResult.Select(s => new ResultRankModel() { id = s.StudentCurrentID, Fail = s.Result != "Pass", Percentage = Convert.ToDecimal(s.Percentage) }).ToList();
157	                                List<ResultRankModel> RankList = new CCEReportRepository().GetResultRank(RankProfile.Id == 0 ? null : (short?)RankProfile.Id, StudentRank);
158	
159	                                model.FinalResult.ForEach(f =>
160	                                {
161	                                    int? rank = RankList.FirstOrDefault(d => d.id == f.StudentCurrentID)?.Rank;
162	                                    f.Rank = rank.HasValue ? rank.Value : 0;
163	                                });
164	                                model.FinalResult.ForEach(f =>
165	                                {
166	                                    f.Percentage = f.Result == "Failed" && RankProfile.HidePercentageWhenFail == true ? 0 : f.Percentage;
167	                                    f.Grade = f.Result == "Failed" && RankProfile.HideGradeWhenFail == true ? null : f.Grade;
168	                                });
169	                            }
170	                            else
171	                            {
172	                                var defaultProfile = _RankProfile.GetDefaultExamProfile(null, param.SchoolID, null).Result;
173	                                string hp, hg, hper;
174	                                int temp;
175	                                RankProfile = new RankProfile
176	                                {
177	                                    Id = 0,
178	                                    HidePercentageWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HidePercentageWhenFail", out hp) &&
179	                                        int.TryParse(hp, out temp) && temp == 1,
180	                                    HideGradeWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HideGradeWhenFail", out hg) &&
181	                                        int.TryParse(hg, out temp) && temp == 1,
182	                                    HidePercentileWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HidePercentileWhenFail", out hper) &&
183	                                        int.TryParse(hper, out temp) && temp == 1
184	                                };
185	
186	                                // Rule : give rank only to pass student
187	                                model.FinalResult.OrderByDescending(a => a.Percentage)
188	                                    .Where(x => x.Result == "Pass").ToList().ForEach(x => x.Rank = rankData.Where(y => y.Percentage == x.Percentage).Select(y => y.Rank).FirstOrDefault());
189	
190	                                model.FinalResult.ForEach(f =>
191	                                {
192	                                    f.Percentage = f.Result == "Failed" && RankProfile.HidePercentageWhenFail == true ? 0 : f.Percentage;
193	                                    f.Grade = f.Result == "Failed" && RankProfile.HideGradeWhenFail == true ? null : f.Grade;
194	                                });
195	                            }
196	                        }
197	                    }
198	                }
199	
200	                model.ConsolidateResultList = model.ConsolidateResultList.OrderBy(x => Convert.ToInt32(string.IsNullOrEmpty(x.RollNo) ? "0" : x.RollNo)).ThenBy(o => o.StudentCurrentID).ThenBy(o => o.DisplayOrder).ToList();
201	                model.FinalResult = model.FinalResult.OrderBy(x => Convert.ToInt32(string.IsNullOrEmpty(x.RollNo) ? "0" : x.RollNo)).ThenBy(o => o.StudentCurrentID).ToList();
202	
203	                var dt = model.ConsolidateResultList;
204	
205	                // Dynamic Kendo Grid Configuration 
206	                var uniqueSubjects = dt
207	                    .Select(r => new
208	                    {
209	                        SubjectID = r.SubjectID,
210	                        SubjectExamTypeID = r.SubjectExamTypeID,
211	                        SubjectIDName = (r.SubjectIDName ?? "").Trim(),
212	                        DisplayOrder = r.DisplayOrder,
213	                        PassingMarks = r.PassingMarks,
214	                        Totaltotalmarks = r.Totaltotalmarks
215	                    })
216	                    .GroupBy(x => new { x.SubjectID, x.SubjectExamTypeID, x.SubjectIDName })
217	                    .Select(g => g.First())
218	                    .OrderBy(o => o.DisplayOrder).ThenBy(r => r.SubjectID)
219	                    .ToList();
220	
221	                var columns = new List<object>
222	                {
223	                    new { field = "RollNo", title = "Roll No", width = "110", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;", @class = "setcenter" }, headerAttributes = new { style = "text-align:center;", @class = "setcenter" } },
224	                    new { field = "StudentName", title = "Student Name", width = "220", filterable = new { multi = true, search = true } },
