if (gridId === "KConsolidateResultReport") {
            var sheet = e.workbook.sheets[0];

            // Use the LAST "header" row (leaf row: Marks/Special/Grace/.../%/Grade/Result/Rank),
            // not the first ("header")[0] which is the grouped row (Gujarati/Final Result/...)
            // and has far fewer cells due to colSpan — that mismatch was shifting indices.
            var headerRows = sheet.rows.filter(function (r) { return r.type === "header"; });
            var header = headerRows[headerRows.length - 1];

            // textAlign is NOT a real Kendo excel-export property — it's silently ignored.
            // hAlign is what actually controls alignment in the generated xlsx.
            function setAlign(cell, align) {
                if (!cell) return;
                cell.hAlign = align;
                cell.textAlign = align; // harmless, kept for consistency
            }

            // Build a left/center map per leaf column index, once
            var isLeftCol = {};
            if (header && header.cells) {
                header.cells.forEach(function (cell, index) {
                    var text = (cell.value || "").toString().trim();
                    isLeftCol[index] = (text === "%");
                });
            }

            sheet.rows.forEach(function (row) {
                if (!row.cells) return;

                if (row.type === "header") {
                    row.cells.forEach(function (cell) { setAlign(cell, "center"); });
                    return;
                }

                if (row.type === "footer" || row.type === "group-footer") {
                    row.cells.forEach(function (cell) {
                        if (typeof cell.value === "string") {
                            cell.value = cell.value.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, "").trim();
                        }
                        cell.bold = true;
                        setAlign(cell, "center");
                    });
                    return;
                }

                // data rows
                row.cells.forEach(function (cell, index) {
                    if (cell.value === null || cell.value === undefined) return;
                    if (typeof cell.value === "string") {
                        cell.value = cell.value.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, "").trim();
                    }
                    setAlign(cell, isLeftCol[index] ? "left" : "center");
                });
            });
        }

