if (gridId === "KConsolidateResultReport") {
            var sheet = e.workbook.sheets[0];

            // Use the LAST "header" row (leaf row: Marks/Special/Grace/.../%/Grade/Result/Rank),
            // not the first ("header")[0] which is the grouped row (Gujarati/Final Result/...)
            // and has far fewer cells due to colSpan — that mismatch was shifting indices.
            var headerRows = sheet.rows.filter(function (r) { return r.type === "header"; });
            var header = headerRows[headerRows.length - 1];

            // textAlign is NOT a real Kendo excel-export property — it's silently ignored.
            // hAlign is what actually controls alignment in the generated xlsx.
            function setAlign(cell, align) {
                if (!cell) return;
                cell.hAlign = align;
                cell.textAlign = align; // harmless, kept for consistency
            }

            // Build a left/center map per leaf column index, once
            var isLeftCol = {};
            if (header && header.cells) {
                header.cells.forEach(function (cell, index) {
                    var text = (cell.value || "").toString().trim();
                    isLeftCol[index] = (text === "%");
                    // LOG: print column name when it's marked as left-aligned
                    if (isLeftCol[index]) {
                        console.log("Left-aligned column detected:", text, "at index", index);
                    }
                });
            }

            sheet.rows.forEach(function (row) {
                if (!row.cells) return;

                if (row.type === "header") {
                    row.cells.forEach(function (cell) { setAlign(cell, "center"); });
                    return;
                }

                if (row.type === "footer" || row.type === "group-footer") {
                    row.cells.forEach(function (cell) {
                        if (typeof cell.value === "string") {
                            cell.value = cell.value.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, "").trim();
                        }
                        cell.bold = true;
                        setAlign(cell, "center");
                    });
                    return;
                }

                // data rows
                row.cells.forEach(function (cell, index) {
                    if (cell.value === null || cell.value === undefined) return;
                    if (typeof cell.value === "string") {
                        cell.value = cell.value.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, "").trim();
                    }
                    var align = isLeftCol[index] ? "left" : "center";
                    // LOG: print when applying left alignment to data cells
                    if (align === "left") {
                        console.log("Applying LEFT alignment to column index", index, "value:", cell.value);
                    }
                    setAlign(cell, align);
                });
            });
        }

tools.description:
Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.
